const effectUUID = "Compendium.joes-pf2-stuff.joes-items-pf2.Item.thBmNMc7Fesavouw"; // Your effect's UUID

// Load the effect item by UUID
const effectItem = await fromUuid(effectUUID);

if (!effectItem) {
  ui.notifications.error("Could not find the effect using the provided UUID.");
  return;
}

const selectedTokens = canvas.tokens.controlled;

if (selectedTokens.length === 0) {
  ui.notifications.warn("No tokens selected.");
  return;
}

for (const token of selectedTokens) {
  const actor = token.actor;
  if (!actor) continue;

  const hasEffect = actor.items.find(i => i.name === effectItem.name && i.type === "effect");
  if (hasEffect) {
    ui.notifications.info(`${actor.name} already has the effect "${effectItem.name}".`);
    continue;
  }

  await actor.createEmbeddedDocuments("Item", [effectItem.toObject()]);
  ChatMessage.create({
    content: `${actor.name} gains the effect: ${effectItem.name}`,
    speaker: ChatMessage.getSpeaker({ actor: actor })
  });
}
